      if (referrer) {
        user.referredBy = referrer.solanaAddress;
        db.referrals.push({
          id: `ref-${Math.random().toString(36).substring(2, 11)}`,
          referrerAddress: referrer.solanaAddress,
          refereeAddress: solanaAddress,
          createdAt: new Date().toISOString()
